 * Modal Dialog Controller
 * 
 * Manages the delete confirmation dialog with proper focus management,
 * accessibility, and keyboard support.
 */

class DeleteConfirmDialog {
  constructor() {
    this.dialog = document.getElementById('delete-confirm-dialog');
    this.cancelBtn = this.dialog.querySelector('[data-close]');
    this.confirmBtn = this.dialog.querySelector('[data-confirm]');
    this.deleteBtns = document.querySelectorAll('.trigger');
    this.currentTrigger = null;
    this.currentImageName = null;

    this.init();
  }

  init() {
    // Set up event listeners for all delete buttons
    this.deleteBtns.forEach((btn) => {
      btn.addEventListener('click', (e) => this.openDialog(e.target));
    });

    // Cancel button closes dialog
    this.cancelBtn.addEventListener('click', () => this.closeDialog('cancel'));

    // Confirm button closes with delete action
    this.confirmBtn.addEventListener('click', () => this.closeDialog('delete'));

    // Escape key closes dialog
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.dialog.open) {
        this.closeDialog('cancel');
      }
    });

    // Handle backdrop click (close on outside click)
    this.dialog.addEventListener('click', (e) => {
      if (e.target === this.dialog) {
        this.closeDialog('cancel');
      }
    });

    // Handle dialog close event for focus restoration
    this.dialog.addEventListener('close', () => {
      this.handleDialogClose();
    });
  }

  openDialog(triggerElement) {
    this.currentTrigger = triggerElement;

    // Extract the image name from the aria-label (e.g., "Delete Mountain Landscape image")
    const ariaLabel = triggerElement.getAttribute('aria-label');
    this.currentImageName = ariaLabel
      ? ariaLabel.replace(/^Delete\s+/, '').replace(/\s+image$/, '')
      : 'image';

    // Update dialog heading to include the image name
    const heading = this.dialog.querySelector('#dialog-heading');
    heading.textContent = `Delete ${this.currentImageName}?`;

    // Show the modal
    this.dialog.showModal();

    // Move focus to cancel button (safe default, doesn't focus destructive action)
    this.cancelBtn.focus();
  }

  closeDialog(action) {
    this.dialog.close(action);
  }

  handleDialogClose() {
    const returnValue = this.dialog.returnValue;

    if (returnValue === 'delete') {
      // Simulate deletion action
      if (this.currentTrigger) {
        const card = this.currentTrigger.closest('.image-card');
        if (card) {
          // Add a fade-out animation
          card.style.opacity = '0';
          card.style.transform = 'scale(0.95)';
          card.style.transition = 'all 300ms ease-in-out';

          setTimeout(() => {
            card.remove();
            this.announceToScreenReader(
              `${this.currentImageName} image deleted from library.`
            );
          }, 300);
        }
      }
    } else {
      // Cancelled - just restore focus
      if (this.currentTrigger && document.contains(this.currentTrigger)) {
        this.currentTrigger.focus();
      }
    }

    // Reset state
    this.currentTrigger = null;
    this.currentImageName = null;
  }

  /**
   * Announce messages to screen reader users
   */
  announceToScreenReader(message) {
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.setAttribute('aria-atomic', 'true');
    announcement.style.position = 'absolute';
    announcement.style.left = '-10000px';
    announcement.textContent = message;

    document.body.appendChild(announcement);

    // Remove after announcement
    setTimeout(() => announcement.remove(), 1000);
  }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  new DeleteConfirmDialog();
});
