async function runInteractiveA11yTests() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Use file:// URL to load the HTML with external resources
  const htmlPath = path.resolve(__dirname, 'index.html');
  const fileUrl = `file://${htmlPath}`;

  await page.goto(fileUrl, { waitUntil: 'load' });

  // Wait for script to initialize
  await page.waitForTimeout(500);

  // Test 1: Dialog is closed by default
  const dialogOpen1 = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return dialog.open;
  });

  // Test 2: Click trigger opens dialog
  await page.click('.trigger');
  const dialogOpen2 = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return dialog.open;
  });

  // Test 3: Dialog has proper focus management
  const focusedElement = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    if (!dialog.open) return null;
    return document.activeElement.getAttribute('data-close') !== null ? 'cancel-btn' : 'unknown';
  });

  // Test 4: Escape key closes dialog
  await page.keyboard.press('Escape');
  const dialogOpen3 = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return dialog.open;
  });

  // Test 5: Trigger has class "trigger"
  const hasTriggerClass = await page.evaluate(() => {
    const triggers = document.querySelectorAll('.trigger');
    return triggers.length > 0;
  });

  // Test 6: Dialog has aria-labelledby
  const hasLabelledBy = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return dialog.hasAttribute('aria-labelledby');
  });

  // Test 7: Heading exists with proper ID
  const headingExists = await page.evaluate(() => {
    const heading = document.getElementById('dialog-heading');
    return heading !== null && heading.textContent.includes('Delete');
  });

  await browser.close();

  const results = {
    'Dialog closed by default': dialogOpen1 === false,
    'Dialog opens on trigger click': dialogOpen2 === true,
    'Focus moves to cancel button on open': focusedElement === 'cancel-btn',
    'Escape key closes dialog': dialogOpen3 === false,
    'Trigger buttons have "trigger" class': hasTriggerClass === true,
    'Dialog has aria-labelledby': hasLabelledBy === true,
    'Heading exists with proper ID': headingExists === true
  };

  console.log('Interactive A11y Tests:');
  Object.entries(results).forEach(([test, passed]) => {
    console.log(`${passed ? '✓' : '✗'} ${test}`);
  });

  const allPassed = Object.values(results).every(v => v === true);
  console.log(`\nResult: ${allPassed ? 'PASS' : 'FAIL'}`);

  return allPassed;
}

runInteractiveA11yTests().then(passed => {
  process.exit(passed ? 0 : 1);
});
